INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (418, 1, 'TCP_NODELAY', '소켓 옵션 **TCP_NODELAY** 는 무엇을 할까요?', '작은 패킷을 모으는 알고리즘이에요.', NULL, NULL, '[]', 'choice', '["keep-alive 프로브를 켠다", "부분 프레임을 모아 한꺼번에 보낸다", "Nagle 알고리즘을 비활성화한다", "혼잡 제어 알고리즘을 바꾼다"]', 2, 'tcp(7) 문서는 TCP_NODELAY 가 Nagle 알고리즘을 비활성화하며, 설정하지 않으면 Nagle 알고리즘이 적용된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 2, 'TCP_CORK', '소켓 옵션 **TCP_CORK** 는 어떻게 동작할까요?', '코르크 마개처럼 막아요.', NULL, NULL, '[]', 'choice', '["모든 패킷을 즉시 보내 지연을 없앤다", "해제할 때 모아 둔 프레임을 보낸다", "연결이 끊긴 소켓을 즉시 닫는다", "수신 윈도우 크기를 줄인다"]', 1, '문서는 TCP_CORK 가 부분 프레임을 보내지 않고 해제하면 대기 중인 프레임을 모두 전송하며 200ms 상한이 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 3, 'SO_KEEPALIVE', 'keep-alive 프로브는 **언제** 보내질까요?', '소켓 옵션이 필요해요.', NULL, NULL, '[]', 'choice', '["SO_KEEPALIVE 가 활성화된 경우에만", "TCP 연결이 있으면 항상", "tcp_keepalive_time 이 0 일 때만", "수신 윈도우가 0 이 되었을 때만"]', 0, '문서는 keep-alive 프로브가 SO_KEEPALIVE 옵션이 활성화된 경우에만 전송된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 4, 'keepalive 시간', '`tcp_keepalive_time` 의 **기본값** 은 얼마일까요?', '2시간이에요.', NULL, NULL, '[]', 'choice', '["75초", "60초", "600초", "7200초"]', 3, '문서는 tcp_keepalive_time 기본이 7200초(2시간), tcp_keepalive_intvl 기본이 75초, tcp_keepalive_probes 기본이 9회라고 설명합니다.', NULL, NULL, NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 5, 'syncookies 기본', '`tcp_syncookies` 의 **기본값 1** 은 무엇을 뜻할까요?', '큐가 넘칠 때만이에요.', NULL, NULL, '[]', 'choice', '["항상 syncookie 를 보낸다", "syncookie 를 쓰지 않는다", "큐가 넘칠 때에만 syncookie 를 보낸다", "재전송 때만 syncookie 를 보낸다"]', 2, '문서는 tcp_syncookies 가 SYN flood 방어 수단이며 기본값 1 은 큐 overflow 시에만, 0 은 비활성화, 2 는 무조건 전송이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 6, 'SYN 백로그', '`man 7 tcp` 문서가 적은 `tcp_max_syn_backlog` 의 **기본값** 은 얼마일까요?', '256 으로 시작해요.', NULL, NULL, '[]', 'choice', '["16", "256", "8192", "65535"]', 1, '문서는 tcp_max_syn_backlog 가 승인되지 않은 연결 요청 큐의 최대 크기이며 기본 256 이고 메모리가 128MB 이상이면 1024, 32MB 이하이면 128 로 조정된다고 설명합니다. 실제 서버의 값은 메모리와 커널 버전에 따라 다를 수 있으니 `sysctl net.ipv4.tcp_max_syn_backlog` 로 확인하세요.', NULL, NULL, NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 7, 'fin_timeout', '`tcp_fin_timeout` 의 **기본값** 은 얼마일까요?', '1분이에요.', NULL, NULL, '[]', 'choice', '["60초", "10초", "180초", "7200초"]', 0, '문서는 tcp_fin_timeout 이 최종 FIN 을 기다리는 시간이며 기본 60초(Linux 2.2 에서는 180초)라고 설명합니다.', NULL, NULL, NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 8, 'tcp_retries2', '`tcp_retries2` 는 무엇을 정할까요?', '연결 상태에서의 재전송이에요.', NULL, NULL, '[]', 'choice', '["SYN 을 재전송하는 최대 횟수", "keep-alive 프로브의 최대 횟수", "ACK 를 지연하는 최대 시간", "연결 상태에서 재전송하는 최대 횟수"]', 3, '문서는 tcp_retries2 가 연결 상태에서 패킷을 재전송하는 최대 횟수이며 기본 15회이고 약 13~30분에 해당한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 9, 'window scaling', '`tcp_window_scaling` 을 켜면 가능한 것은 무엇일까요?', 'RFC 1323 이에요.', NULL, NULL, '[]', 'choice', '["연결마다 윈도우를 0 으로 줄인다", "재전송 횟수를 늘린다", "64kB 를 넘는 윈도우를 쓸 수 있다", "손실 패킷을 선택적으로 확인한다"]', 2, '문서는 tcp_window_scaling 이 RFC 1323 window scaling 으로 64kB 를 넘는 윈도우를 허용하며 기본 활성화라고 설명합니다. 선택적 확인(SACK)은 tcp_sack 입니다.', NULL, NULL, NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 10, 'SYN flood 방어', 'SYN flood 방어 수단인 sysctl 이름의 마지막 부분입니다. 빈칸을 채우세요.', '"쿠키" 가 들어가요.', NULL, NULL, '[]', 'fill', '["syncookies", "sack", "timestamps", "window_scaling"]', NULL, 'tcp_syncookies 는 SYN flood 방어 수단이며 최후의 수단으로만 쓰도록 권장됩니다.', '[0]', 'net.ipv4.tcp_{0} = 1', NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 11, 'Nagle 끄기', 'Nagle 알고리즘을 **끄는** 소켓 옵션입니다. 빈칸을 채우세요.', '"지연 없음" 이에요.', NULL, NULL, '[]', 'fill', '["TCP_NODELAY", "TCP_CORK", "TCP_KEEPIDLE", "SO_KEEPALIVE"]', NULL, 'TCP_NODELAY 는 Nagle 알고리즘을 비활성화합니다. TCP_CORK 는 부분 프레임을 모아 둡니다.', '[0]', 'setsockopt(fd, IPPROTO_TCP, {0}, &one, sizeof(one))', NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]'),
  (418, 12, 'keep-alive 동작', 'keep-alive 가 동작하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '켜기 → 유휴 → 반복 → 한도예요.', NULL, NULL, '[]', 'order', '["소켓에 `SO_KEEPALIVE` 를 켠다", "연결이 `tcp_keepalive_time` 동안 유휴이면 프로브를 보내기 시작한다", "응답이 없으면 `tcp_keepalive_intvl` 간격으로 프로브를 반복한다", "`tcp_keepalive_probes` 만큼 보내도 응답이 없으면 연결을 끊는다"]', NULL, '문서의 keep-alive 항목 설명을 이은 일반 절차입니다. 마지막 단계(연결 종료)는 문서가 직접 적지 않았습니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "tcp(7) man page", "url": "https://man7.org/linux/man-pages/man7/tcp.7.html"}]');
